 var launches=new List<ProcessStartInfo>();s.LaunchOverride=info=>launches.Add(info);GuntConfiguration.Save(root,"apps",new Dictionary<string,object>{{"terminal",Process.GetCurrentProcess().MainModule.FileName},{"code",Process.GetCurrentProcess().MainModule.FileName}});s.LaunchProject(p.Id,"folder");s.LaunchProject(p.Id,"ide");s.LaunchProject(p.Id,"terminal");s.LaunchProject(p.Id,"repository");Check(launches.Count==4&&!launches.Any(x=>x.Arguments.Contains("EncodedCommand")),"Selecting/ordinary launches never execute custom command");s.LaunchProject(p.Id,"command");Check(launches.Last().Arguments.Contains("EncodedCommand"),"Explicit command uses encoded payload");Check(s.State("project-recent").ContainsKey(p.Id),"Successful launch records recency");Directory.Delete(dir);Reject(()=>s.LaunchProject(p.Id,"folder"),"Missing directory launch rejected without recreation");Check(!Directory.Exists(dir),"Missing folder not silently created");s.DeleteProject(p.Id);Check(s.Projects().Length==0,"Project delete persists");
