 var live=Path.Combine(root,"lively");var library=Path.Combine(live,"Library");var package=Path.Combine(library,"wallpapers","real-installed-fixture");Directory.CreateDirectory(package);File.WriteAllText(Path.Combine(package,"LivelyInfo.json"),"{\"Title\":\"Fixture\",\"FileName\":\"index.html\"}");File.WriteAllText(Path.Combine(live,"Settings.json"),s.Json.Serialize(new {WallpaperDir=library}));s.LivelyDataOverride=live;Check(s.Wallpapers().Length==1&&s.Wallpapers()[0].Type=="HTML / WebGL","Gallery only discovers local metadata");s.FavoriteWallpaper(package);Check(s.Wallpapers()[0].Favorite,"Wallpaper favorite persists");Check(launches.Count==5,"Gallery discovery/favorite never changes wallpaper");Reject(()=>s.FavoriteWallpaper("unknown"),"Unknown wallpaper rejected");var candidate=s.ConfigurationSnapshots().First(path=>s.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path)).ContainsKey("width")&&Convert.ToInt32(s.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path))["width"])!=Convert.ToInt32(s.Read("monitor")["width"]));Check(s.SnapshotPreview(candidate).Length>0,"Snapshot preview contains real differences");int currentWidth=Convert.ToInt32(s.Read("monitor")["width"]);s.RestoreConfigurationSnapshot(candidate);Check(Convert.ToInt32(s.Read("monitor")["width"])!=currentWidth,"Selected snapshot restores real configuration");s.Undo();Check(Convert.ToInt32(s.Read("monitor")["width"])==currentWidth,"Snapshot restoration can be undone");Reject(()=>s.RestoreConfigurationSnapshot(Path.Combine(root,"config","monitor.json")),"Non-backup snapshot rejected");string custom=s.SaveWorkspaceProfile("Test profile");s.RenameProfile(custom,"Changed profile");Check(s.Profiles().First(x=>x.Id==custom).Name=="Changed profile","User profile save rename persist");s.DeleteProfile(custom);Check(!s.Profiles().Any(x=>x.Id==custom),"User profile deletion archives source");Check(Directory.Exists(Path.Combine(root,"backups")),"Version backups created");Console.WriteLine("VERIFIED "+count);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
